          ]
        },
        {
          "stage": "identity",
          "focus": "商品身份",
          "sentences": [
            {
              "display_text": "这双是足弓支撑静音防滑厚底凉拖鞋，小蛮腰女款，来自 Joy Share 生活选物。",
              "spoken_text": "这双是足弓支撑静音防滑厚底凉拖鞋，小蛮腰女款，来自 Joy Share 生活选物。",
              "kind": "product_claim",
              "fact_ids": ["NAME"]
            },
            {
              "display_text": "专为女性足部曲线打造，一般版型，厚底平底设计。",
              "spoken_text": "专为女性足部曲线打造，一般版型，厚底平底设计。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "足弓支撑与厚底软弹",
          "sentences": [
            {
              "display_text": "先看足弓支撑这个点。脚底中间有了承托，站着洗菜、叠衣服，脚掌没那么容易觉得累。",
              "spoken_text": "先看足弓支撑这个点。脚底中间有了承托，站着洗菜、叠衣服，脚掌没那么容易觉得累。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "它不是硬邦邦顶着你，而是顺着足部曲线给一点托住的感觉。",
              "spoken_text": "它不是硬邦邦顶着你，而是顺着足部曲线给一点托住的感觉。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "加上小蛮腰厚底，走起来软弹缓震，在家来回走动踏实不少。",
              "spoken_text": "加上小蛮腰厚底，走起来软弹缓震，在家来回走动踏实不少。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "静音与防滑",
          "sentences": [
            {
              "display_text": "晚上家人休息了，你在屋里走动，鞋底静音设计能减少打扰。",
              "spoken_text": "晚上家人休息了，你在屋里走动，鞋底静音设计能减少打扰。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "鞋底也有防滑特性，浴室或室内走动合适；当然，浴室走动还是要留意地面。",
              "spoken_text": "鞋底也有防滑特性，浴室或室内走动合适；当然，浴室走动还是要留意地面。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "材质防臭快干易清洗",
