        {
          "stage": "benefit",
          "focus": "轻便与多场景",
          "sentences": [
            {
              "display_text": "整双鞋轻便，出门旅行塞进行李箱不占地方。",
              "spoken_text": "整双鞋轻便，出门旅行塞进行李箱不占地方。",
